	/**
	 * Default Constructor
	 */
    public CartService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new CartEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(CartRepository.class) );
		this.validator		= applicationContext.getBean(CartValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Cart
	 */
		public Cart createCart( CreateCartCommand command ) {

		Cart entity = new Cart();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setCartId( command.getCartId() );
            entity.setCartNumber( command.getCartNumber() );
            entity.setCreatedAt( command.getCreatedAt() );
            entity.setCurrency( command.getCurrency() );
            entity.setShippingAddress( command.getShippingAddress() );
            entity.setBillingAddress( command.getBillingAddress() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Cart {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateCartCommand
	 * @return		Cart
	 */
	public Cart updateCart( UpdateCartCommand command ) {

		Cart entity = new Cart();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setCartId( command.getCartId() );
            entity.setCartNumber( command.getCartNumber() );
            entity.setCreatedAt( command.getCreatedAt() );
            entity.setCurrency( command.getCurrency() );
            entity.setShippingAddress( command.getShippingAddress() );
            entity.setBillingAddress( command.getBillingAddress() );
            entity.setCustomer( command.getCustomer() );
            entity.setChannel( command.getChannel() );
            entity.setItems( command.getItems() );
            entity.setAppliedPromotions( command.getAppliedPromotions() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Cart {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteCartCommand
	 */
	public void delete( DeleteCartCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getCartId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Cart {0} ", id );

	}

	/**
	 * Method to retrieve the Cart via CartFetchOneSummary
	 * @param 	summary CartFetchOneSummary
	 * @return 	CartFetchOneResponse
	 */
	public Cart getCart( CartFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "CartFetchOneSummary arg cannot be null" );

		Cart entity = null;
		UUID id = summary.getCartId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Cart using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Carts
	 *
	 * @return 	List<Cart>
	 */
    public List<Cart> getAllCart() {
		List<Cart> list = projector.findAll( new FindAllCartQuery() );
		return list;
	}

	/**
	 * assign Customer on Cart
	 * @param		command AssignCustomerToCartCommand
	 */
	public void assignCustomer( AssignCustomerToCartCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignCustomer(command.getCartId(), command.getAssignment());

	}

	/**
	 * unAssign Customer on Cart
	 * @param		command UnAssignCustomerFromCartCommand
	 */
	public void unAssignCustomer( UnAssignCustomerFromCartCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignCustomer(command.getCartId());
	}
	
